end=s.index('func (s *Service) setStatus(')
new='''// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due. When the gateway is unavailable the invoice stays open, to be paid later, and the subscription keeps its status.
//
// A period is renewed once, however many calls run at once or in turn: moving the period and storing its invoice is one
// step, and only the call that takes that step charges the invoice. RenewDue goes on past a subscription that fails, and
// returns the errors together after trying them all. It returns how many subscriptions it renewed or canceled; a renewal
// whose charge failed counts, since its period moved.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	var errs []error
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			errs = append(errs, err)
			break
		}
		renewed, err := s.renew(ctx, sub, now)
		if renewed {
			n++
		}
		if err != nil {
			errs = append(errs, fmt.Errorf("renew %s: %w", sub.ID, err))
		}
	}
	return n, errors.Join(errs...)
}

// renew renews one due subscription, as read from the store. It reports whether it renewed or canceled it: false with no
// error means another renewal of the same period got there first.
func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return false, store.ErrNotFound
	}
	from, to := sub.CurrentPeriodStart, sub.CurrentPeriodEnd
	if sub.CancelAtPeriodEnd {
		canceled, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			if x.Status == store.Canceled || !x.CurrentPeriodStart.Equal(from) || !x.CurrentPeriodEnd.Equal(to) {
				return store.ErrNotDue
			}
			x.Status, x.CanceledAt = store.Canceled, &to
			return nil
		})
		if errors.Is(err, store.ErrNotDue) {
			return false, nil
		}
		if err != nil {
			return false, err
		}
		s.publish(ctx, sub.OrgID, "subscription.canceled", canceled)
		return true, nil
	}
	start := now
	end := billing.AddInterval(start, plan.Interval)
	var inv *store.Invoice
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		draft := s.draftInvoice(sub, plan, from, to)
		inv = &draft
	case plan.UsageType == store.Licensed:
		draft := s.draftInvoice(sub, plan, start, end)
		inv = &draft
	}
	updated, created, err := s.Store.RenewSubscription(sub.OrgID, sub.ID, from, to, start, end, inv, now)
	if errors.Is(err, store.ErrNotDue) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	// Nothing to charge (a metered trial's period) counts as paid.
	paid, chargeErr := true, error(nil)
	if created != nil {
		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": created.ID, "subscription_id": sub.ID})
		paid, chargeErr = s.charge(ctx, *created)
	}
	if chargeErr == nil {
		next := store.Active
		if !paid {
			next = store.PastDue
		}
		updated, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			if x.Status != store.Canceled {
				x.Status = next
			}
			return nil
		})
		if err != nil {
			return true, err
		}
	}
	s.publish(ctx, sub.OrgID, "subscription.updated", updated)
	if chargeErr != nil {
		return true, fmt.Errorf("charge invoice %s: %w", created.ID, chargeErr)
	}
	return true, nil
}

// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
// It reports false when the charge was declined.
func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
	inv, err := s.Store.CreateInvoice(s.draftInvoice(sub, plan, start, end), s.Clock.Now())
	if err != nil {
		return false, err
	}
	s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
	return s.charge(ctx, inv)
}

// draftInvoice is the invoice of one period of a subscription: its lines, and the period it bills.
func (s *Service) draftInvoice(sub store.Subscription, plan store.Plan, start, end time.Time) store.Invoice {
	var lines []store.Line
	period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
	switch plan.UsageType {
	case store.Licensed:
		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	ps, pe := start, end
	return store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}
}

// charge charges an open invoice to its customer's default payment method. It reports false when the charge was declined,
// and an error when the gateway was unavailable, which leaves the invoice open. An invoice with nothing to charge is marked
// paid; one whose customer has no payment method stays open and counts as paid here (it is paid by hand).
func (s *Service) charge(ctx context.Context, inv store.Invoice) (bool, error) {
	_, _, err := s.Payments.Pay(ctx, inv.OrgID, inv.ID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

